AutoStory_Descriptor::AutoStory_Descriptor()
    : SingleSwitchProgramDescriptor(
        "PokemonFRLG:AutoStory",
        Pokemon::STRING_POKEMON + " FRLG", "AutoStory",
        "Programs/PokemonFRLG/AutoStory.html",
        "Play the FireRed/LeafGreen story from the bedroom to the Hall of Fame and on after it "
        "(the legendary Pokemon, the Sevii Islands, 60 species for the National POKeDEX, the Ruby and the "
        "Sapphire, the roaming legendary with the Master Ball, Mewtwo, then the Pokedex collection: "
        "what the chosen game can still register in the grass, caves and Safari Zone), "
        "on routes generated from the game's map data.",
        //  PocketPilot's own program, still being tested: it shows as "beta".
        PanelQualityStanding::OFFICIAL_BETA,
        ProgramControllerClass::StandardController_RequiresPrecision,
        FeedbackType::REQUIRED,
        AllowCommandsWhenRunning::DISABLE_COMMANDS,
        {
            //  Multi-line OCR (battle text, dialogs, bag descriptions).
            "PaddleOCRDetection",
        }
    )
{}

struct AutoStory_Descriptor::Stats : public StatsTracker{
    Stats()
        : segments(m_stats["Segments"])
        , steps(m_stats["Steps"])
        , wild_battles(m_stats["Wild Battles"])
        , trainer_battles(m_stats["Trainer Battles"])
        , resets(m_stats["Resets"])
        , errors(m_stats["Errors"])
        , shinies(m_stats["Shinies"])
    {
        m_display_order.emplace_back("Segments");
        m_display_order.emplace_back("Steps");
        m_display_order.emplace_back("Wild Battles");
        m_display_order.emplace_back("Trainer Battles");
        m_display_order.emplace_back("Resets", HIDDEN_IF_ZERO);
        m_display_order.emplace_back("Errors", HIDDEN_IF_ZERO);
        m_display_order.emplace_back("Shinies", HIDDEN_IF_ZERO);
    }

    std::atomic<uint64_t>& segments;
    std::atomic<uint64_t>& steps;
    std::atomic<uint64_t>& wild_battles;
    std::atomic<uint64_t>& trainer_battles;
    std::atomic<uint64_t>& resets;
    std::atomic<uint64_t>& errors;
    std::atomic<uint64_t>& shinies;
};

std::unique_ptr<StatsTracker> AutoStory_Descriptor::make_stats() const{
    return std::unique_ptr<StatsTracker>(new Stats());
}


namespace{


//  A TALK step's other spot (p2 = 1; dir = the step there, p3 = the
//  facing: 1 up, 2 down, 3 left, 4 right).
StoryTalkAlt talk_alt(const StoryStep& step){
    StoryTalkAlt alt;
    if (step.p2 != 1){
        return alt;
    }
    alt.on = true;
    alt.move = step.dir;
    alt.face =
        step.p3 == 1 ? DPAD_UP :
        step.p3 == 2 ? DPAD_DOWN :
        step.p3 == 3 ? DPAD_LEFT :
        step.p3 == 4 ? DPAD_RIGHT : DPAD_NONE;
    return alt;
}

//  A text file the program wrote with string_to_file(): that puts a UTF-8
//  BOM in front (build 76 read "Charmander" as another starter).
bool read_text_file(const std::string& path, std::string& text){
    if (!file_to_string(path, text)){
        return false;
    }
    if (text.rfind("\xef\xbb\xbf", 0) == 0){
        text.erase(0, 3);
    }
    return true;
}

const StoryScript& script_for(AutoStory::Starter starter){
    switch (starter){
    case AutoStory::Starter::BULBASAUR:     return AutoStoryData::story_BULBASAUR();
    case AutoStory::Starter::SQUIRTLE:      return AutoStoryData::story_SQUIRTLE();
    case AutoStory::Starter::CHARMANDER:    return AutoStoryData::story_CHARMANDER();
    }
    return AutoStoryData::story_BULBASAUR();
}

const char* starter_name(AutoStory::Starter starter){
    switch (starter){
    case AutoStory::Starter::BULBASAUR:     return "Bulbasaur";
    case AutoStory::Starter::SQUIRTLE:      return "Squirtle";
    case AutoStory::Starter::CHARMANDER:    return "Charmander";
    }
    return "?";
}

//  The segments are the same for every starter (only some steps differ).
const IntegerEnumDropdownDatabase& segment_database(){
    static const IntegerEnumDropdownDatabase database = [](){
        IntegerEnumDropdownDatabase ret;
        const StoryScript& script = AutoStoryData::story_BULBASAUR();
        for (size_t i = 0; i < script.segment_count; i++){
            const StorySegment& segment = script.segments[i];
            std::string slug;
            for (const char* p = segment.id; *p; p++){
                slug += (char)std::tolower((unsigned char)*p);
            }
            ret.add(i, slug, std::string(segment.id) + ": " + segment.title);
        }
        return ret;
    }();
    return database;
}

std::string segment_name(const StorySegment& segment){
    return std::string(segment.id) + " (" + segment.title + ")";
}

}   //  namespace

const StoryScript& autostory_routes(){
    return AutoStoryData::story_BULBASAUR();
}

namespace{

Button button_from_name(const std::string& name){
    if (name == "A") return BUTTON_A;
    if (name == "B") return BUTTON_B;
    if (name == "PLUS") return BUTTON_PLUS;
    return BUTTON_B;
}
DpadPosition dpad_from_name(const std::string& name){
    if (name == "UP") return DPAD_UP;
    if (name == "DOWN") return DPAD_DOWN;
    if (name == "LEFT") return DPAD_LEFT;
    if (name == "RIGHT") return DPAD_RIGHT;
    return DPAD_NONE;
}


}   //  namespace



